add('GET','/api/admin/registrations',ctx=>{need('registrations')(ctx);let q=`SELECT r.*,s.name stage_name,g.name grade_name,t.name teacher_name,gr.code group_code FROM registrations r JOIN stages s ON s.id=r.stage_id JOIN grades g ON g.id=r.grade_id LEFT JOIN teachers t ON t.id=r.teacher_id LEFT JOIN groups gr ON gr.id=r.group_id WHERE 1=1`,params=[];if(ctx.user.role==='teacher'){q+=" AND r.id IN (SELECT DISTINCT e.registration_id FROM student_enrollments e JOIN groups eg ON eg.id=e.group_id WHERE eg.teacher_id=? AND e.status IN ('active','waiting'))";params.push(Number(ctx.user.teacher_id||0))}if(ctx.query.status){q+=' AND r.status=?';params.push(ctx.query.status)}if(ctx.query.group_id){q+=" AND r.id IN (SELECT registration_id FROM student_enrollments WHERE group_id=? AND status IN ('active','waiting'))";params.push(Number(ctx.query.group_id))}if(ctx.query.q){q+=' AND (r.student_name LIKE ? OR r.parent_name LIKE ? OR r.student_phone LIKE ? OR r.parent_phone LIKE ? OR r.request_code LIKE ? OR r.tracking_code LIKE ?)';const s=`%${ctx.query.q}%`;params.push(s,s,s,s,s,s)}q+=' ORDER BY r.id DESC';json(ctx.res,200,{registrations:all(q,...params)})});
add('PATCH',/^\/api\/admin\/registrations\/(?<id>\d+)$/,async ctx=>{needLevel(ctx,50);const id=Number(ctx.params.id),o=get('SELECT * FROM registrations WHERE id=?',id);if(!o)throw Object.assign(new Error('غير موجود'),{status:404});const allowed=['student_name','student_phone','parent_name','parent_phone','subject_text','teacher_id','status','cancellation_reason','student_note','admin_note'],fields=allowed.filter(f=>Object.prototype.hasOwnProperty.call(ctx.body,f));if(!fields.length)return json(ctx.res,200,{ok:true,registration:regDetail(id)});if(fields.includes('status')&&ctx.body.status==='cancelled'&&!String(ctx.body.cancellation_reason||o.cancellation_reason||'').trim())throw Object.assign(new Error('اكتب سبب الإلغاء'),{status:400});const nextStudent=cleanPhone(fields.includes('student_phone')?ctx.body.student_phone:o.student_phone),nextParent=cleanPhone(fields.includes('parent_phone')?ctx.body.parent_phone:o.parent_phone);if(!validPhone(nextStudent))throw Object.assign(new Error('رقم هاتف الطالب غير صحيح'),{status:400});if(!validPhone(nextParent))throw Object.assign(new Error('رقم هاتف ولي الأمر غير صحيح'),{status:400});if(nextStudent===nextParent)throw Object.assign(new Error('رقم ولي الأمر يجب أن يكون مختلفًا عن رقم الطالب'),{status:400});if(get('SELECT 1 FROM registrations WHERE student_phone=? AND id<>? LIMIT 1',nextStudent,id))throw Object.assign(new Error('رقم الطالب مستخدم في ملف طالب آخر'),{status:409});if(fields.includes('status')&&['new','contacted','reserved','confirmed'].includes(ctx.body.status)&&!['new','contacted','reserved','confirmed'].includes(o.status)&&o.group_id&&groupCounts(o.group_id).remaining<=0)throw Object.assign(new Error('المجموعة مكتملة. اترك الطالب في قائمة الانتظار أو انقله إلى مجموعة أخرى.'),{status:409});const vals=fields.map(f=>['teacher_id'].includes(f)?(Number(ctx.body[f])||null):(f.includes('phone')?cleanPhone(ctx.body[f]):ctx.body[f]));run(`UPDATE registrations SET ${fields.map(f=>`${f}=?`).join(',')},updated_at=CURRENT_TIMESTAMP WHERE id=?`,...vals,id);if(ctx.body.status==='cancelled')run("UPDATE student_enrollments SET status='cancelled',end_date=COALESCE(end_date,date('now')),change_reason=COALESCE(change_reason,?),updated_at=CURRENT_TIMESTAMP WHERE registration_id=? AND status IN ('active','waiting')",ctx.body.cancellation_reason||'إلغاء التسجيل',id);rebalanceWaitlist(o.group_id);let tracking=null;if(ctx.body.status==='confirmed'&&(o.status!=='confirmed'||!o.tracking_code)){tracking=await ensureTrackingAndNotify(id,ctx,true)}log(ctx,'update','registrations',id,ctx.body);json(ctx.res,200,{registration:regDetail(id),tracking})});
add('POST',/^\/api\/admin\/registrations\/(?<id>\d+)\/transfer$/,ctx=>{needLevel(ctx,50);const id=Number(ctx.params.id),r=get('SELECT * FROM registrations WHERE id=?',id),gid=Number(ctx.body.group_id);if(!r)throw Object.assign(new Error('الطالب غير موجود'),{status:404});const g=get('SELECT * FROM groups WHERE id=? AND active=1',gid);if(!g)throw Object.assign(new Error('المجموعة غير موجودة'),{status:404});if(Number(r.group_id)===gid)return json(ctx.res,200,{registration:regDetail(id),unchanged:true});const oldGroup=r.group_id,c=groupCounts(gid),status=c.remaining>0?'reserved':'waiting',enrollStatus=c.remaining>0?'active':'waiting',pos=enrollStatus==='waiting'?c.waiting+1:null;tx(()=>{const old=get("SELECT * FROM student_enrollments WHERE registration_id=? AND group_id=? AND status IN ('active','waiting') ORDER BY id DESC LIMIT 1",id,oldGroup||0);if(old)run("UPDATE student_enrollments SET status='ended',end_date=date('now'),change_reason=?,updated_at=CURRENT_TIMESTAMP WHERE id=?",ctx.body.reason||'نقل إلى مجموعة أخرى',old.id);run('INSERT INTO student_enrollments(registration_id,group_id,subject_id,subject_text,teacher_id,status,waitlist_position,start_date,change_reason) VALUES(?,?,?,?,?,?,?,?,?)',id,gid,g.subject_id||null,g.subject_text,g.teacher_id||null,enrollStatus,pos,new Date().toISOString().slice(0,10),ctx.body.reason||'نقل من المجموعة السابقة');run('UPDATE registrations SET group_id=?,teacher_id=?,stage_id=?,grade_id=?,subject_id=?,subject_text=?,status=?,waitlist_position=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',gid,g.teacher_id,g.stage_id,g.grade_id,g.subject_id,g.subject_text,status,pos,id)});rebalanceWaitlist(oldGroup);rebalanceWaitlist(gid);log(ctx,'transfer','registrations',id,{from:oldGroup,to:gid,status});json(ctx.res,200,{registration:regDetail(id)})});
