add('POST',/^\/api\/admin\/registrations\/(?<id>\d+)\/enrollments$/,ctx=>{needLevel(ctx,50);const id=Number(ctx.params.id),r=get('SELECT * FROM registrations WHERE id=?',id),gid=Number(ctx.body.group_id);if(!r)throw Object.assign(new Error('الطالب غير موجود'),{status:404});const g=get('SELECT * FROM groups WHERE id=? AND active=1',gid);if(!g)throw Object.assign(new Error('المجموعة غير موجودة أو موقوفة'),{status:404});if(get("SELECT 1 FROM student_enrollments WHERE registration_id=? AND group_id=? AND status IN ('active','waiting')",id,gid))throw Object.assign(new Error('الطالب مسجل بالفعل في هذه المجموعة'),{status:409});if(get("SELECT 1 FROM student_enrollments WHERE registration_id=? AND subject_text=? AND status='active'",id,g.subject_text)&&!bool(ctx.body.allow_same_subject))throw Object.assign(new Error('الطالب لديه اشتراك نشط في نفس المادة. انقل الاشتراك الحالي بدل إضافة نسخة أخرى.'),{status:409});const c=groupCounts(gid),st=c.remaining>0?'active':'waiting',pos=st==='waiting'?c.waiting+1:null,info=run('INSERT INTO student_enrollments(registration_id,group_id,subject_id,subject_text,teacher_id,status,waitlist_position,start_date,change_reason) VALUES(?,?,?,?,?,?,?,?,?)',id,gid,g.subject_id||null,g.subject_text,g.teacher_id||null,st,pos,new Date().toISOString().slice(0,10),ctx.body.reason||'إضافة مادة/مجموعة جديدة');log(ctx,'add_enrollment','student_enrollments',info.lastInsertRowid,{registration_id:id,group_id:gid,status:st});json(ctx.res,201,{id:info.lastInsertRowid,status:st,waitlist_position:pos})});
