add('PATCH',/^\/api\/admin\/attendance\/records\/(?<id>\d+)$/,ctx=>{need('attendance')(ctx);const rec=get('SELECT ar.id,s.group_id FROM attendance_records ar JOIN attendance_sessions s ON s.id=ar.session_id WHERE ar.id=?',Number(ctx.params.id));if(!rec)throw Object.assign(new Error('غير موجود'),{status:404});ensureTeacherGroup(ctx.user,rec.group_id);if(!['unmarked','present','absent','excused'].includes(ctx.body.status))throw Object.assign(new Error('حالة غير صحيحة'),{status:400});run('UPDATE attendance_records SET status=?,note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',ctx.body.status,ctx.body.note||'',Number(ctx.params.id));log(ctx,'update','attendance_records',ctx.params.id,ctx.body);json(ctx.res,200,{ok:true})});

add('GET','/api/admin/subscriptions',ctx=>{need('subscriptions')(ctx);let q=`SELECT s.*,r.request_code,r.student_name,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.subscription_id=s.id),0) paid FROM subscriptions s JOIN registrations r ON r.id=s.registration_id`,params=[];if(ctx.query.registration_id){q+=' WHERE s.registration_id=?';params.push(Number(ctx.query.registration_id))}q+=' ORDER BY s.period DESC,s.id DESC';json(ctx.res,200,{subscriptions:all(q,...params).map(x=>({...x,balance:Math.max(0,(x.amount-x.discount)-x.paid)}))})});
add('POST','/api/admin/subscriptions',ctx=>{need('subscriptions')(ctx);try{const b=ctx.body;if(Number(b.amount)<0||Number(b.discount||0)<0||Number(b.discount||0)>Number(b.amount))throw new Error('قيمة الاشتراك أو الخصم غير صحيحة');const info=run('INSERT INTO subscriptions(registration_id,period,amount,due_date,discount,note) VALUES(?,?,?,?,?,?)',Number(b.registration_id),b.period,Number(b.amount),b.due_date||null,Number(b.discount)||0,b.note||'');log(ctx,'create','subscriptions',info.lastInsertRowid,b);json(ctx.res,201,{id:info.lastInsertRowid})}catch{throw Object.assign(new Error('يوجد اشتراك لنفس الطالب والفترة أو البيانات غير صحيحة'),{status:400})}});
add('PATCH',/^\/api\/admin\/subscriptions\/(?<id>\d+)$/,ctx=>{need('subscriptions')(ctx);const id=Number(ctx.params.id),o=get('SELECT * FROM subscriptions WHERE id=?',id);if(!o)throw Object.assign(new Error('غير موجود'),{status:404});const b={...o,...ctx.body};if(Number(b.amount)<0||Number(b.discount||0)<0||Number(b.discount||0)>Number(b.amount))throw Object.assign(new Error('قيمة الاشتراك أو الخصم غير صحيحة'),{status:400});run('UPDATE subscriptions SET period=?,amount=?,due_date=?,discount=?,note=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',b.period,Number(b.amount),b.due_date||null,Number(b.discount)||0,b.note||'',id);log(ctx,'update','subscriptions',id,ctx.body);json(ctx.res,200,{ok:true})});
add('GET','/api/admin/payments',ctx=>{need('payments')(ctx);let q=`SELECT p.*,r.request_code,r.student_name FROM payments p JOIN registrations r ON r.id=p.registration_id`,params=[];if(ctx.query.registration_id){q+=' WHERE p.registration_id=?';params.push(Number(ctx.query.registration_id))}q+=' ORDER BY p.paid_at DESC,p.id DESC';json(ctx.res,200,{payments:all(q,...params)})});
add('POST','/api/admin/payments',ctx=>{need('payments')(ctx);const b=ctx.body,regId=Number(b.registration_id),subId=Number(b.subscription_id)||null,amount=Number(b.amount);if(!regId||!get('SELECT 1 FROM registrations WHERE id=?',regId)||!Number.isFinite(amount)||amount<=0)throw Object.assign(new Error('بيانات الدفعة غير صحيحة'),{status:400});if(subId){const sub=get(`SELECT s.*,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.subscription_id=s.id),0) paid FROM subscriptions s WHERE s.id=? AND s.registration_id=?`,subId,regId);if(!sub)throw Object.assign(new Error('الاشتراك لا يخص هذا الطالب'),{status:400});const balance=Math.max(0,(Number(sub.amount)-Number(sub.discount))-Number(sub.paid));if(amount>balance+0.001)throw Object.assign(new Error(`المبلغ أكبر من المتبقي على الاشتراك (${balance.toFixed(2)} جنيه)`),{status:400})}const rn=receiptNo(),info=run('INSERT INTO payments(registration_id,subscription_id,amount,method,reference,receipt_no,paid_at,note,created_by) VALUES(?,?,?,?,?,?,?,?,?)',regId,subId,amount,b.method||'cash',b.reference||'',rn,b.paid_at||new Date().toISOString().slice(0,10),b.note||'',ctx.user.id);log(ctx,'create','payments',info.lastInsertRowid,{...b,receipt_no:rn});json(ctx.res,201,{id:info.lastInsertRowid,receipt_no:rn})});
add('GET',/^\/api\/admin\/payments\/(?<id>\d+)\/receipt$/,ctx=>{need('payments')(ctx);const p=get(`SELECT p.*,r.student_name,r.request_code FROM payments p JOIN registrations r ON r.id=p.registration_id WHERE p.id=?`,Number(ctx.params.id));if(!p)throw Object.assign(new Error('غير موجود'),{status:404});html(ctx.res,200,receiptHtml(p))});

add('POST','/api/admin/upload',ctx=>{need('uploads')(ctx);const f=ctx.body.files?.file;if(!f)throw Object.assign(new Error('اختر ملفًا'),{status:400});if(f.data.length>12*1024*1024)throw Object.assign(new Error('الملف أكبر من 12MB'),{status:413});if(!/^(image\/(jpeg|png|webp|gif)|application\/pdf|text\/plain)/.test(f.ctype))throw Object.assign(new Error('نوع الملف غير مسموح'),{status:400});const extByType={'image/jpeg':'.jpg','image/png':'.png','image/webp':'.webp','image/gif':'.gif','application/pdf':'.pdf','text/plain':'.txt'},ext=extByType[f.ctype]||'.bin',name=`${Date.now()}-${crypto.randomBytes(6).toString('hex')}${ext}`,dest=path.join(UPLOADS,name);fs.writeFileSync(dest,f.data);log(ctx,'upload','files',name,{original:f.filename,size:f.data.length,type:f.ctype});json(ctx.res,201,{url:`/uploads/${name}`,name:f.filename,size:f.data.length,mimetype:f.ctype})},{multipart:true});

add('GET','/api/admin/export/registrations.xlsx',ctx=>{need('registrations')(ctx);let q=`SELECT r.request_code "رقم الطلب",r.student_name "اسم الطالب",r.student_phone "هاتف الطالب",r.parent_name "ولي الأمر",r.parent_phone "هاتف ولي الأمر",s.name "المرحلة",g.name "الصف",r.subject_text "المادة",t.name "المدرس",gr.code "المجموعة",r.status "الحالة",r.admin_note "ملاحظات",r.created_at "تاريخ التسجيل" FROM registrations r JOIN stages s ON s.id=r.stage_id JOIN grades g ON g.id=r.grade_id LEFT JOIN teachers t ON t.id=r.teacher_id LEFT JOIN groups gr ON gr.id=r.group_id`,params=[];if(ctx.user.role==='teacher'){q+=" WHERE r.id IN (SELECT DISTINCT e.registration_id FROM student_enrollments e JOIN groups eg ON eg.id=e.group_id WHERE eg.teacher_id=? AND e.status IN ('active','waiting'))";params.push(Number(ctx.user.teacher_id||0))}q+=' ORDER BY r.id DESC';const rows=all(q,...params),buf=makeXlsx(rows,'Registrations');ctx.res.writeHead(200,{'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Disposition':'attachment; filename="saeed-registrations.xlsx"','Content-Length':buf.length});ctx.res.end(buf)});
add('POST','/api/admin/import/registrations',ctx=>{needLevel(ctx,50);const f=ctx.body.files?.file;if(!f)throw Object.assign(new Error('اختر ملف Excel أو CSV'),{status:400});let rows;if(/\.csv$/i.test(f.filename))rows=parseCsv(f.data.toString('utf8'));else rows=parseXlsx(f.data);let inserted=0,errors=[];const stages=all('SELECT id,name,code FROM stages'),gradeRows=all('SELECT id,name,code,stage_id FROM grades');tx(()=>rows.forEach((r,i)=>{try{const student=r['اسم الطالب']||r.student_name,parent=r['ولي الأمر']||r.parent_name,sp=cleanPhone(r['هاتف الطالب']||r.student_phone),pp=cleanPhone(r['هاتف ولي الأمر']||r.parent_phone),stageVal=r['المرحلة']||r.stage,stage=stages.find(x=>x.name===stageVal||x.code===stageVal||x.id===Number(r.stage_id)),gradeVal=r['الصف']||r.grade,grade=gradeRows.find(g=>g.stage_id===stage?.id&&(g.name===gradeVal||g.code===gradeVal||g.id===Number(r.grade_id))),subject=String(r['المادة']||r.subject_text||'').trim();if(!student||!parent||!validPhone(sp)||!validPhone(pp)||!stage||!grade||!subject)throw new Error('بيانات ناقصة');if(sp===pp)throw new Error('رقم ولي الأمر يساوي رقم الطالب');if(get('SELECT 1 FROM registrations WHERE student_phone=? LIMIT 1',sp))throw new Error('رقم الطالب مسجل بالفعل');let code;do{code=requestCode()}while(get('SELECT 1 FROM registrations WHERE request_code=?',code));const ri=run('INSERT INTO registrations(request_code,student_name,student_phone,parent_name,parent_phone,stage_id,grade_id,subject_text,status) VALUES(?,?,?,?,?,?,?,?,?)',code,student,sp,parent,pp,stage.id,grade.id,subject,'new').lastInsertRowid;run('INSERT INTO student_enrollments(registration_id,subject_text,status,start_date,change_reason) VALUES(?,?,?,?,?)',ri,subject,'active',new Date().toISOString().slice(0,10),'استيراد من Excel');inserted++}catch(e){errors.push({row:i+2,error:e.message})}}));log(ctx,'import','registrations','bulk',{inserted,errors:errors.length});json(ctx.res,200,{inserted,errors})},{multipart:true});
function parseCsv(s){const lines=s.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return[];const split=l=>{const a=[];let cur='',q=false;for(let i=0;i<l.length;i++){const c=l[i];if(c==='"'&&l[i+1]==='"'&&q){cur+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){a.push(cur);cur=''}else cur+=c}a.push(cur);return a};const h=split(lines.shift());return lines.map(l=>Object.fromEntries(split(l).map((v,i)=>[h[i]||`col${i+1}`,v])))}

add('GET','/api/admin/reports/revenue',ctx=>{need('reports')(ctx);const from=ctx.query.from||'0000-01-01',to=ctx.query.to||'9999-12-31',daily=all('SELECT paid_at date,SUM(amount) total,COUNT(*) payments FROM payments WHERE paid_at BETWEEN ? AND ? GROUP BY paid_at ORDER BY paid_at',from,to);json(ctx.res,200,{from,to,total:daily.reduce((s,x)=>s+x.total,0),daily})});
