add('GET',/^\/api\/admin\/reports\/student\/(?<id>\d+)$/,ctx=>{need('registrations')(ctx);ensureTeacherRegistration(ctx.user,Number(ctx.params.id));const r=regDetail(Number(ctx.params.id));if(!r)throw Object.assign(new Error('غير موجود'),{status:404});const enrollments=all(`SELECT e.*,gr.code group_code,gr.days,gr.time,gr.room,COALESCE(t.name,'') teacher_name,s.name stage_name,g.name grade_name FROM student_enrollments e LEFT JOIN groups gr ON gr.id=e.group_id LEFT JOIN teachers t ON t.id=COALESCE(e.teacher_id,gr.teacher_id) LEFT JOIN stages s ON s.id=gr.stage_id LEFT JOIN grades g ON g.id=gr.grade_id WHERE e.registration_id=? ORDER BY e.id DESC`,r.id),subscriptions=all(`SELECT s.*,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.subscription_id=s.id),0) paid FROM subscriptions s WHERE s.registration_id=? ORDER BY period`,r.id).map(x=>({...x,balance:Math.max(0,(x.amount-x.discount)-x.paid)})),payments=all('SELECT * FROM payments WHERE registration_id=? ORDER BY paid_at',r.id),attendance=all(`SELECT ses.session_date,ses.topic,ar.status,ar.note,gr.code group_code,gr.subject_text,t.name teacher_name FROM attendance_records ar JOIN attendance_sessions ses ON ses.id=ar.session_id JOIN groups gr ON gr.id=ses.group_id LEFT JOIN teachers t ON t.id=gr.teacher_id WHERE ar.registration_id=? ORDER BY ses.session_date DESC`,r.id),grades=all(`SELECT sg.*,COALESCE(s.name,gr.subject_text,'') subject_name,gr.code group_code,t.name teacher_name FROM student_grades sg LEFT JOIN subjects s ON s.id=sg.subject_id LEFT JOIN groups gr ON gr.id=sg.group_id LEFT JOIN teachers t ON t.id=sg.teacher_id WHERE sg.registration_id=? ORDER BY COALESCE(sg.exam_date,sg.created_at) DESC`,r.id),messages=all(`SELECT m.*,gr.code group_code,CASE WHEN mr.read_at IS NULL THEN 0 ELSE 1 END is_read FROM messages m LEFT JOIN groups gr ON gr.id=m.group_id LEFT JOIN message_reads mr ON mr.message_id=m.id AND mr.registration_id=? WHERE m.registration_id=? OR EXISTS(SELECT 1 FROM message_recipients mrp WHERE mrp.message_id=m.id AND mrp.registration_id=?) OR (m.registration_id IS NULL AND m.group_id IS NULL) ORDER BY m.id DESC`,r.id,r.id,r.id),notifications=all('SELECT * FROM notification_logs WHERE registration_id=? ORDER BY id DESC LIMIT 50',r.id),attendanceSummary={total:attendance.filter(x=>x.status!=='unmarked').length,present:attendance.filter(x=>x.status==='present').length,absent:attendance.filter(x=>x.status==='absent').length,excused:attendance.filter(x=>x.status==='excused').length};json(ctx.res,200,{registration:r,enrollments,subscriptions,payments,attendance,attendanceSummary,grades,messages,notifications})});
