function setCors(req,res){
  const origin=String(req.headers.origin||'');
  if(origin){res.setHeader('Access-Control-Allow-Origin',origin);res.setHeader('Vary','Origin')}
  res.setHeader('Access-Control-Allow-Methods','GET,POST,PATCH,DELETE,OPTIONS');
  res.setHeader('Access-Control-Allow-Headers','Content-Type,X-Saeed-Request,X-Saeed-Admin-Token,X-Saeed-Portal-Token');
  res.setHeader('Access-Control-Max-Age','86400');
}
function setSecurity(res){res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('X-Frame-Options','SAMEORIGIN');res.setHeader('Referrer-Policy','strict-origin-when-cross-origin');res.setHeader('Permissions-Policy','camera=(), microphone=(), geolocation=()');res.setHeader('Cross-Origin-Resource-Policy','cross-origin');res.setHeader('Content-Security-Policy',"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data: https:; connect-src 'self'; frame-src https://www.google.com https://maps.google.com; form-action 'self'; base-uri 'self'; object-src 'none'")}
async function handle(req,res){setSecurity(res);setCors(req,res);if(req.method==='OPTIONS'){res.writeHead(204);return res.end()}const u=new URL(req.url,`http://${req.headers.host||'localhost'}`),pathname=decodeURIComponent(u.pathname),method=req.method.toUpperCase(),ctx={req,res,query:Object.fromEntries(u.searchParams),ip:ip(req),user:userFromReq(req),body:{},params:{}};if(pathname.startsWith('/api/')){if(pathname.startsWith('/api/admin/')&&ctx.user?.must_change_password)return json(res,428,{error:'يجب تغيير كلمة المرور المؤقتة أولًا'});if(!['GET','HEAD','OPTIONS'].includes(method)&&!pathname.startsWith('/api/auth/')&&!pathname.startsWith('/api/public/')&&!pathname.startsWith('/api/portal/')&&req.headers['x-saeed-request']!=='1')return json(res,403,{error:'طلب إداري غير موثوق'});for(const r of routes){if(r.method!==method)continue;const params=matchRoute(r.pattern,pathname);if(params==null)continue;ctx.params=params;try{ctx.body=await parseBody(req);if(ctx.body?.fields){ctx.body={...ctx.body.fields,files:ctx.body.files}}await r.handler(ctx);return}catch(e){console.error(method,pathname,e);return json(res,e.status||500,{error:e.message||'حدث خطأ في الخادم'})}}return json(res,404,{error:'المسار غير موجود'})}
  return serveStatic(pathname,res)}
function serveStatic(pathname,res){let rel=pathname==='/'?'index.html':pathname.replace(/^\/+/,''),base=PUBLIC_ROOT;if(rel.startsWith('uploads/')){base=APP_ROOT;rel=rel}const full=path.resolve(base,rel);if(!(full.startsWith(PUBLIC_ROOT)||full.startsWith(UPLOADS)))return html(res,403,'Forbidden');let file=full;try{if(fs.statSync(file).isDirectory())file=path.join(file,'index.html')}catch{}if(!fs.existsSync(file)||!fs.statSync(file).isFile()){file=path.join(PUBLIC_ROOT,'404.html');if(!fs.existsSync(file))return html(res,404,'404');res.statusCode=404}const ext=path.extname(file).toLowerCase(),data=fs.readFileSync(file);res.writeHead(res.statusCode||200,{'Content-Type':mime[ext]||'application/octet-stream','Cache-Control':PROD&&pathname.startsWith('/uploads/')?'public,max-age=604800':'no-cache','Content-Length':data.length});res.end(data)}
const server=http.createServer(handle);server.listen(PORT,HOST,()=>console.log(`Saeed Center Pro running: http://${HOST}:${PORT}`));
